input <- c(15, NA, 0, 20, 70)
stopifnot(is.numeric(input))
valid <- input[is.finite(input) & input >= 1 & input <= 60]
kept <- head(valid, 3)
cat(length(kept), "\n", sep = "")
if (length(kept) == 0) {
  cat("no valid values\n")
} else {
  cat(sprintf("%.1f", mean(kept)), "\n", sep = "")
}

